package vn.codegym.salesinventory.controller;
import jakarta.servlet.http.*;import java.math.*;import vn.codegym.salesinventory.service.*;
public final class ProductServlet extends PortalServlet {
 protected void get(HttpServletRequest r,HttpServletResponse s)throws Exception{var service=new ProductService(source());r.setAttribute("categories",new CategoryService(source()).tree());int page=value(r,"page").isEmpty()?1:Math.toIntExact(number(r,"page"));r.setAttribute("pageNo",page);r.setAttribute("products",service.list(actor(r).id(),value(r,"q"),value(r,"category").isEmpty()?null:number(r,"category"),value(r,"status"),page));if(!value(r,"id").isEmpty())r.setAttribute("edit",service.find(actor(r).id(),number(r,"id")));view(r,s,"catalog/products");}
 protected void post(HttpServletRequest r,HttpServletResponse s)throws Exception{var service=new ProductService(source());long id=value(r,"id").isEmpty()?0:number(r,"id");if(value(r,"action").equals("delete"))service.delete(actor(r).id(),id);else{BigDecimal cost=null;if(!value(r,"cost").isEmpty()){access(r).require("COST_WRITE");cost=vn.codegym.salesinventory.validation.CatalogValidation.decimal(value(r,"cost"),4,false);}String key=null;var file=r.getPart("image");ImageStorage images=null;if(file!=null&&file.getSize()>0){images=ImageStorage.configured();key=images.save(file.getInputStream().readNBytes(ImageStorage.MAX_BYTES+1));}try{service.save(actor(r).id(),id,new ProductService.Input(value(r,"sku"),value(r,"name"),number(r,"category"),value(r,"baseUnit"),value(r,"packaging"),cost,key,value(r,"status"),value(r,"version").isEmpty()?0:number(r,"version")));}catch(Exception e){if(key!=null)images.remove(key);throw e;}}redirect(r,s,"/catalog/products");}
}
